const raw = process.argv[2];
if (raw === '--help') {
  console.log('Usage: node scripts/count-errors.mjs <json-array>');
  process.exit(0);
}
try {
  const records = JSON.parse(raw ?? '');
  if (!Array.isArray(records)) throw new Error('Expected a JSON array');
  console.log(JSON.stringify({ errors: records.length }));
} catch {
  console.error('Expected a JSON array');
  process.exitCode = 2;
}
